    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Construct a nontrivial right triangle with integer sides
# using Euclid parameters (u > v, gcd(u,v)=1, opposite parity)
# and a special scale t = s*(u^2+v^2) so that AD, BD have the form
# AD = s*(u^2 - v^2)^2 and BD = 4*s*u^2*v^2, making CD integer.

import math
def coprime(a,b):
    # simple gcd
    while b:
        a,b = b, a%b
    return a==1

primes = [2,3,5,7,11,13]
for _ in range(1000):
    # pick u,v
    u = rng.randint(6, 60)
    v_choices = [x for x in range(2, u-1) if ((u - x) % 2 == 1) and coprime(u, x)]
    if not v_choices:
        continue
    v = rng.choice(v_choices)
    # choose s as product of 2 or 3 distinct small primes, possibly with exponents 1 or 2
    k = rng.choice([2,3])
    factors = rng.sample(primes, k)
    s = 1
    for p in factors:
        e = rng.choice([1,2])
        s *= p**e
    # compute AD and BD
    ad = s * (u*u - v*v)**2
    bd = 4 * s * (u*u) * (v*v)
    # enforce difficulty: large values, and ensure fraction reduction isn't trivial
    if ad < 10**5 or bd < 10**5:
        continue
    # m = 2uv, n = u^2 + v^2 (this will be used by verifier indirectly via AD, BD)
    m = 2*u*v
    n = u*u + v*v
    # ensure nontrivial denominator
    if n < 200 or m < 50:
        continue
    # avoid overly huge numbers to keep problems reasonable
    if ad > 10**14 or bd > 10**14:
        continue
    return {'ad': ad, 'bd': bd}
# fallback deterministic (rarely used)
u, v = 15, 8
s = 2*3*5
ad = s * (u*u - v*v)**2
bd = 4 * s * (u*u) * (v*v)
return {'ad': ad, 'bd': bd}

