# verify they are perfect squares
x = math.isqrt(X2)
y = math.isqrt(Y2)
if x*x != X2 or y*y != Y2:
    return (False, None)
# compute n from x^2 + y^2 = (u^2 + v^2)^2
N2 = X2 + Y2
n = math.isqrt(N2)
if n*n != N2:
